1	//! The envelope wired into `AgentResponse`: sections, `budget:` and `provenance:` together (spec 07, slice 5).
2	
3	use michi_core::kv::{KvItem, KvValue};
4	use michi_core::toon::Value;
5	use michi_core::{AgentResponse, BudgetSummary, OutputFormat, ProvenanceBlock, RecoveryHint, Section, SectionCost};
6	use proptest::prelude::*;
7	
8	mod support;
9	use support::toon_parser::{decode, Node, Prim};
10	
11	fn fields(names: &[&str]) -> Vec<String> {
12	    names.iter().map(|s| (*s).to_string()).collect()
13	}
14	
15	fn symbols() -> Section {
16	    Section::toon("brief.symbols", fields(&["name"]), vec![vec![Value::from("RetryPolicy")]]).total_count(Some(40))
17	}
18	
19	fn refs() -> Section {
20	    Section::toon("brief.refs", fields(&["symbol"]), vec![vec![Value::from("RetryPolicy")]])
21	}
22	
23	fn long_cell_section(name: &str) -> Section {
24	    Section::toon(name, fields(&["c"]), vec![vec![Value::from("x".repeat(50))]])
25	}
26	
27	fn valid(text: &str) -> support::toon_parser::Doc {
28	    decode(text).unwrap_or_else(|e| panic!("not conformant TOON: {e}\n{text}"))
29	}
30	
31	fn json(r: &AgentResponse) -> serde_json::Value {
32	    let text = r.render(OutputFormat::Json);
33	    serde_json::from_str(&text).unwrap_or_else(|e| panic!("invalid JSON: {e}\n{text}"))
34	}
35	
36	#[test]
37	fn full_envelope_renders_in_the_documented_order() {
38	    let budget = BudgetSummary::new()
39	        .tokens_used(10)
40	        .section(SectionCost::new("brief.symbols", 1).total(40))
41	        .section(SectionCost::new("brief.refs", 1));
42	    let r = AgentResponse::new("brief")
43	        .section(symbols())
44	        .section(refs())
45	        .budget(budget)
46	        .provenance(ProvenanceBlock::new().entry("analyzer", "ra").fingerprint("abc"))
47	        .hint("narrow it")
48	        .recovery_hint(RecoveryHint::new("search"));
49	    let out = r.render(OutputFormat::Text);
50	    let at = |needle: &str| out.find(needle).unwrap_or_else(|| panic!("{needle} missing in\n{out}"));
51	    assert!(at("brief.symbols") < at("brief.refs"));
52	    assert!(at("brief.refs") < at("budget:"));
53	    assert!(at("budget:") < at("sections[2]{name,returned,total,truncated}:"));
54	    assert!(at("sections[2]") < at("provenance:"));
55	    assert!(at("provenance:") < at("help["));
56	    assert!(at("help[") < at("recovery["));
57	    valid(&out);
58	}
59	
60	#[test]
61	fn sugar_and_sections_all_count_as_blocks_for_the_rollup() {
62	    let budget = || BudgetSummary::new().section(SectionCost::new("a", 1));
63	    // `items()` is a section: it plus one more is two blocks, in call order, roll-up shown.
64	    let two = AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["n"]).section(refs()).budget(budget());
65	    let out = two.render(OutputFormat::Text);
66	    assert!(out.starts_with("t[1]{n}:\n  1\nbrief.refs[1]{symbol}:"), "{out}");
67	    assert!(out.contains("sections[1]{name,returned,total,truncated}:"), "{out}");
68	    // An empty KV section is still a section: two blocks, roll-up shown.
69	    let empty_kv = AgentResponse::new("t").kv_items(vec![]).section(refs()).budget(budget());
70	    assert!(empty_kv.render(OutputFormat::Text).contains("sections["), "{}", empty_kv.render(OutputFormat::Text));
71	    let one = AgentResponse::new("t").section(refs()).budget(budget());
72	    assert!(!one.render(OutputFormat::Text).contains("sections["));
73	    // A single `items()` section: no roll-up either.
74	    let slot_only = AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["n"]).budget(budget());
75	    assert!(!slot_only.render(OutputFormat::Text).contains("sections["));
76	}
