        Some(Hint::new("showing 50 of 120; pass --limit 120 to see all"))
    );
    assert_eq!(outcome.hint(String::from("use offset=50")), Some(Hint::new("showing 50 of 120; use offset=50")));
}

#[test]
fn an_empty_guidance_drops_the_clause() {
