    /// One per response; a second call replaces the first.
    #[must_use] pub fn budget(self, b: BudgetSummary) -> Self;
    /// One per response; a second call replaces the first.
    #[must_use] pub fn provenance(self, p: ProvenanceBlock) -> Self;
}
```

